def isbn_valid(s: str) -> bool:
    if not isinstance(s, str):
        return False

    s = s.replace("-", "").replace(" ", "")

    if len(s) == 10:
        if not all("0" <= c <= "9" for c in s[:9]):
            return False
        if not ("0" <= s[9] <= "9" or s[9] == "X"):
            return False

        digits = [int(c) for c in s[:9]]
        digits.append(10 if s[9] == "X" else int(s[9]))
        return sum((i + 1) * digit for i, digit in enumerate(digits)) % 11 == 0

    if len(s) == 13:
        if not all("0" <= c <= "9" for c in s):
            return False

        return sum(
            int(digit) * (1 if i % 2 == 0 else 3)
            for i, digit in enumerate(s)
        ) % 10 == 0

    return False
